import os
import hmac
import hashlib
import time
import json
from flask import Flask, request, jsonify, abort
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives import hashes
import subprocess
import tempfile

app = Flask(__name__)

# Load signing key for response integrity
RESPONSE_SIGNING_KEY = os.environ.get('RESPONSE_HMAC_KEY', 'default-key')

def sign_response(data):
    """Sign response payload for downstream verification"""
    payload = json.dumps(data, sort_keys=True)
    sig = hmac.new(RESPONSE_SIGNING_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return sig

@app.route('/health')
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

@app.route('/api/v2/render', methods=['POST'])
def render_document():
    """Render a document template with user-provided variables.
    Accepts JSON with 'template_name' and 'variables' dict.
    Templates are Jinja2-like but rendered via pandoc for PDF output."""

    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    template_name = data.get('template_name', '')
    variables = data.get('variables', {})
    output_format = data.get('format', 'pdf')

    # Validate template name - alphanumeric and hyphens only
    if not template_name or not all(c.isalnum() or c in '-_' for c in template_name):
        return jsonify({'error': 'Invalid template name'}), 400

    # Validate output format
    allowed_formats = ['pdf', 'html', 'docx']
    if output_format not in allowed_formats:
        return jsonify({'error': f'Format must be one of {allowed_formats}'}), 400

    template_path = f'/opt/templates/{template_name}.md'
    if not os.path.exists(template_path):
        return jsonify({'error': 'Template not found'}), 404

    # Read template and perform variable substitution
    with open(template_path, 'r') as f:
        content = f.read()

    # Substitute variables into template
    for key, value in variables.items():
        placeholder = '{{' + key + '}}'
        content = content.replace(placeholder, str(value))

    # Write substituted content to temp file and render with pandoc
    with tempfile.NamedTemporaryFile(mode='w', suffix='.md', dir='/tmp/work', delete=False) as tf:
        tf.write(content)
        tf_path = tf.name

    output_path = tf_path.replace('.md', f'.{output_format}')

    try:
        # Build pandoc command
        cmd = f'pandoc {tf_path} -o {output_path} --pdf-engine=xelatex'

        # Add metadata from variables if present
        if 'title' in variables:
            cmd += f' --metadata title="{variables["title"]}"'
        if 'author' in variables:
            cmd += f' --metadata author="{variables["author"]}"'

        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30, cwd='/tmp/work')

        if result.returncode != 0:
            return jsonify({'error': 'Render failed', 'detail': result.stderr.decode()[:500]}), 500

        if os.path.exists(output_path):
            with open(output_path, 'rb') as of:
                rendered = of.read()
            return rendered, 200, {'Content-Type': 'application/pdf' if output_format == 'pdf' else 'application/octet-stream'}
        else:
            return jsonify({'error': 'Output file not generated'}), 500
    finally:
        for p in [tf_path, output_path]:
            if os.path.exists(p):
                os.unlink(p)

@app.route('/api/v2/templates', methods=['GET'])
def list_templates():
    """List available templates"""
    templates = []
    template_dir = '/opt/templates'
    if os.path.isdir(template_dir):
        for f in os.listdir(template_dir):
            if f.endswith('.md'):
                templates.append(f[:-3])
    return jsonify({'templates': templates})

@app.route('/api/v2/preview', methods=['POST'])
def preview_substitution():
    """Preview variable substitution without rendering"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    template_name = data.get('template_name', '')
    variables = data.get('variables', {})

    if not template_name or not all(c.isalnum() or c in '-_' for c in template_name):
        return jsonify({'error': 'Invalid template name'}), 400

    template_path = f'/opt/templates/{template_name}.md'
    if not os.path.exists(template_path):
        return jsonify({'error': 'Template not found'}), 404

    with open(template_path, 'r') as f:
        content = f.read()

    for key, value in variables.items():
        placeholder = '{{' + key + '}}'
        content = content.replace(placeholder, str(value))

    return jsonify({'preview': content[:2000]})

if __name__ == '__main__':
    os.makedirs('/tmp/work', exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
